sections.body:
先把一个能跑的程序摆出来，再回头解释它。新建一个文件叫 `hello.c`，写进去这五行：

```c
#include <stdio.h>

int main(void) {
    printf("你好，C 语言\n");
    return 0;
}
```

在这个平台上点运行就能看到结果。屏幕上出现一行字：

```
你好，C 语言
```

这就是一个完整的 C 程序。它做的事只有一件，往屏幕上打一行字。接下来几节把这五行拆开讲。

字符串里有些字符没法直接敲，要用反斜杠开头的写法表示。

```c
#include <stdio.h>

int main(void) {
    printf("第一行\n第二行\n");
    printf("姓名\t班级\t分数\n");
    printf("李雷\t三班\t92\n");
    printf("路径是 C:\\code\\hello.c\n");
    printf("双引号这么打 \"你好\"\n");
    printf("百分号这么打 100%%\n");
    return 0;
}
```

常用的就这几个：

| 写法 | 表示 |
|---|---|
| `\n` | 换行 |
| `\t` | 制表符，用来对齐列 |
| `\\` | 一个反斜杠 |
| `\"` | 一个双引号 |
| `%%` | 一个百分号，只在 `printf` 的格式串里需要 |

反斜杠在字符串里有特殊含义，所以想打一个真正的反斜杠必须写两个。Windows 路径里全是反斜杠，这个坑很容易踩。

这一章的目标是这个程序：给三科成绩，算出总分和平均分，打印成一张成绩单。

```c
#include <stdio.h>

int main(void) {
    char name[] = "李雷";
    int chinese = 88;
    int math = 95;
    int english = 79;

    int total = chinese + math + english;
    double average = total / 3.0;

    printf("姓名：%s\n", name);
    printf("语文 %d，数学 %d，英语 %d\n", chinese, math, english);
    printf("总分：%d\n", total);
    printf("平均分：%.1f\n", average);
    return 0;
}
```

运行结果：

```
姓名：李雷
语文 88，数学 95，英语 79
总分：262
平均分：87.3
```

这段代码里有三处值得停下来看：变量前面为什么要写 `int` 和 `double`，为什么平均分要除以 `3.0` 而不是 `3`，`printf` 里的 `%d` 和 `%.1f` 是什么。下面逐个讲。

C 里的每个变量都必须先说清楚存什么类型的数据，才能使用。这是它和 Python 最明显的区别。

```c
int chinese = 88;
double average = 87.3;
char grade = 'A';
```

写法是类型在前，名字在后，可以顺手给个初始值。也可以先声明再赋值：

```c
int total;
total = 88 + 95 + 79;
```

**声明了不赋值就直接用，值是随机的**。下面这句打出来的数字每次可能都不一样：

```c
int x;
printf("%d\n", x);
```

gcc 会警告 `'x' is used uninitialized`。养成习惯，声明的时候就给个初值。

变量名只能用字母、数字和下划线，不能用数字开头，也不能和 `int`、`return` 这类关键字重名。名字要能看懂，`total` 比 `t` 好。

把成绩单里写死的分数换成从键盘输入，用 `scanf`。

```c
#include <stdio.h>

int main(void) {
    int chinese, math, english;

    printf("依次输入语文、数学、英语成绩：");
    if (scanf("%d %d %d", &chinese, &math, &english) != 3) {
        printf("输入格式不对\n");
        return 1;
    }

    int total = chinese + math + english;
    printf("总分 %d，平均 %.1f\n", total, total / 3.0);
    return 0;
}
```

`scanf` 和 `printf` 长得像，但有两个地方不一样。

第一，**变量前面要加 `&`**。`&chinese` 的意思是 chinese 这个变量的地址。`scanf` 要往变量里写东西，光有值不行，得知道往哪写。这是第 5 章指针的内容，现在先记住读 `int`、`double`、`char` 都要加 `&`。忘了加 `&` 程序多半会直接崩掉。

第二，**读 `double` 要用 `%lf` 而不是 `%f`**。`printf` 里两个都行，`scanf` 里必须用 `%lf`。

```c
double price;
scanf("%lf", &price);
```

`scanf` 的返回值是成功读到了几个数据。上面判断它是不是等于 3，就能挡住用户乱敲字母的情况。养成检查返回值的习惯，程序会稳很多。

这一章的目标是这个程序：电脑心里有个数，你猜，它告诉你大了还是小了，直到猜中。

```c
#include <stdio.h>

int main(void) {
    int secret = 42;
    int guess = 0;
    int times = 0;

    printf("猜一个 1 到 100 的整数\n");
    while (guess != secret) {
        if (scanf("%d", &guess) != 1) {
            printf("读不到数字，退出\n");
            return 1;
        }
        times++;
        if (guess > secret) {
            printf("大了\n");
        } else if (guess < secret) {
            printf("小了\n");
        } else {
            printf("对了，用了 %d 次\n", times);
        }
    }
    return 0;
}
```

依次输入 50、25、37、42，输出是：

```
猜一个 1 到 100 的整数
大了
小了
小了
对了，用了 4 次
```

这个程序用到了两样新东西。`if` 让程序根据条件走不同的路，`while` 让一段代码反复执行。下面把它们讲清楚。

答案写死成 42 是为了每次结果一样，方便对照。想让它每局都不同，用随机数：

```c
#include <stdlib.h>
#include <time.h>

srand((unsigned)time(NULL));
int secret = rand() % 100 + 1;
```

`srand` 用当前时间做种子，`rand` 取出的余数落在 0 到 99，加 1 就变成 1 到 100。`srand` 整个程序只调一次，放在 `main` 开头。

`if` 后面的条件成立就执行大括号里的语句，不成立就跳过。

```c
int score = 88;

if (score >= 60) {
    printf("及格\n");
} else {
    printf("不及格\n");
}
```

要分成三档以上，用 `else if` 接下去：

```c
if (score >= 90) {
    printf("优秀\n");
} else if (score >= 80) {
    printf("良好\n");
} else if (score >= 60) {
    printf("及格\n");
} else {
    printf("不及格\n");
}
```

**从上往下第一个成立的分支执行完就结束，后面的一律跳过**。所以顺序很重要。上面这段如果把 60 分那一条放最前面，88 分会被判成及格，因为它先撞上了这一条。

大括号在只有一条语句时可以省略，但建议永远写上。下面这段的缩进骗了人，第二行不管条件成不成立都会执行：

```c
if (score >= 60)
    printf("及格\n");
    printf("发证书\n");    /* 这行和 if 无关 */
```

次数已知的重复用 `for`。

```c
for (int i = 1; i <= 5; i++) {
    printf("第 %d 次\n", i);
}
```

括号里三段用分号隔开，各管一件事：

- `int i = 1` 只在开始时执行一次，用来准备计数器。
- `i <= 5` 每轮开始前检查一次，成立才进循环体。
- `i++` 每轮结束后执行一次，等价于 `i = i + 1`。

上面这段打出五行。把条件改成 `i < 5` 就只有四行。边界差一个是很常见的错误，写完循环先想想到底跑几轮。

循环可以嵌套。下面打一张三角形的乘法表：

```c
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 3; i++) {
        for (int j = 1; j <= i; j++) {
            printf("%d*%d=%d\t", j, i, i * j);
        }
        printf("\n");
    }
    return 0;
}
```

外层每转一圈，内层完整跑一遍。内层的上界是 `i`，所以每行的列数逐行增加，形成一个三角。

`i` 声明在 `for` 的括号里，出了循环就不存在了。想在循环外用它，得在外面声明。

次数不确定、靠条件停的重复用 `while`。

```c
int n = 1;
while (n < 100) {
    n = n * 2;
}
printf("%d\n", n);    /* 打出 128 */
```

`while` 先判断条件再执行，条件一开始就不成立的话，循环体一次都不跑。猜数字游戏用 `while` 正合适，因为不知道玩家要猜几次。

**写 `while` 一定要确认循环体里有东西能让条件变假**，否则就是死循环。下面这段永远停不下来，因为 n 一直没变：

```c
int n = 1;
while (n < 100) {
    printf("%d\n", n);
}
```

还有一个 `do while`，它先执行一次再判断条件，所以循环体至少跑一次：

```c
int guess;
do {
    printf("请输入 1 到 100 的数：");
    scanf("%d", &guess);
} while (guess < 1 || guess > 100);
```

这个写法适合先做一次再检查的场合，比如反复要求用户输入直到合法为止。注意 `do while` 末尾有分号。

`break` 立刻跳出整个循环，`continue` 跳过本轮剩下的语句直接进入下一轮。

```c
for (int i = 1; i <= 10; i++) {
    if (i == 5) {
        break;
    }
    printf("%d ", i);
}
/* 打出 1 2 3 4 */
```

```c
for (int i = 1; i <= 10; i++) {
    if (i % 2 == 0) {
        continue;
    }
    printf("%d ", i);
}
/* 打出 1 3 5 7 9 */
```

`break` 常用来提前结束搜索，找到了就没必要接着找：

```c
int nums[6] = {4, 9, 16, 25, 36, 49};
int target = 25;
int found = -1;

for (int i = 0; i < 6; i++) {
    if (nums[i] == target) {
        found = i;
        break;
    }
}
printf("在下标 %d\n", found);
```

要注意的是，**`break` 只跳出最里面那一层循环**。嵌套循环里想一次跳出两层，要么用一个标志变量，要么把内层拆成一个函数用 `return` 出来。

一个变量要和很多个固定值比较时，`switch` 比一长串 `else if` 清楚。

```c
#include <stdio.h>

int main(void) {
    int day = 3;

    switch (day) {
        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
            printf("工作日\n");
            break;
        case 6:
        case 7:
            printf("周末\n");
            break;
        default:
            printf("这不是有效的星期\n");
    }
    return 0;
}
```

规则有三条要记：

- `case` 后面只能跟常量，不能写条件表达式。
- **执行完一个 `case` 不会自动停，会一直往下执行到遇见 `break`**。上面 1 到 5 共用一段代码就是利用了这个特性。忘写 `break` 是很常见的 bug。
- `default` 接住所有没匹配上的情况，放在最后，可以不写但建议写。

`switch` 也能用在 `char` 上，因为字符本质是整数：

```c
switch (grade) {
    case 'A': printf("优秀\n"); break;
    case 'B': printf("良好\n"); break;
    default:  printf("其他\n");
}
```

上一章的游戏所有代码都堆在 `main` 里。这一章把它拆成三个函数，每个函数只管一件事。

```c
#include <stdio.h>

int ask_guess(void);
int judge(int guess, int secret);
void report(int times);

int ask_guess(void) {
    int g = 0;
    printf("请输入你猜的数：");
    if (scanf("%d", &g) != 1) {
        return -1;
    }
    return g;
}

int judge(int guess, int secret) {
    if (guess > secret) {
        return 1;
    }
    if (guess < secret) {
        return -1;
    }
    return 0;
}

void report(int times) {
    printf("猜对了，一共用了 %d 次\n", times);
}

int main(void) {
    int secret = 42;
    int times = 0;

    while (1) {
        int g = ask_guess();
        if (g < 0) {
            printf("输入结束\n");
            return 1;
        }
        times++;

        int r = judge(g, secret);
        if (r > 0) {
            printf("大了\n");
        } else if (r < 0) {
            printf("小了\n");
        } else {
            report(times);
            break;
        }
    }
    return 0;
}
```

行数比原来多，但读起来更清楚。`main` 现在只剩流程，具体怎么读输入、怎么比较、怎么报告，各自关在自己的函数里。想改提示语只用动 `report`，想加输入范围校验只用动 `ask_guess`，不用在一大坨代码里翻。

下面把函数的写法讲清楚。

C 从上往下读代码，用到一个函数时它必须已经出现过。下面这段就违反了这条规矩：

```c
#include <stdio.h>

int main(void) {
    printf("%d\n", add(3, 5));   /* 此时编译器还不认识 add */
    return 0;
}

int add(int a, int b) {
    return a + b;
}
```

gcc 会警告 `implicit declaration of function 'add'`，然后按老规矩假设 `add` 返回 `int`。这次碰巧猜对了，程序还能跑出 8。要是 `add` 返回的是 `double`，结果就完全错了，而且不会有任何提示。C23 标准已经把这件事定成错误，所以见到这条警告必须处理。

有两种改法。

第一种，把 `add` 整个挪到 `main` 前面。函数少的时候够用，但函数一多顺序就难排，因为可能互相调用。

第二种，在文件开头写一行函数原型，只声明不写函数体：

```c
int add(int a, int b);
```

原型就是函数头加一个分号。它告诉编译器有这么个函数、参数和返回值是什么样，函数体可以放在文件任何地方。3.1 节那个程序开头的三行就是原型。

**推荐一律用原型**：所有原型集中放在文件顶部，读代码的人一眼就能看到这个文件提供哪些功能。原型里参数名可以省略，写 `int add(int, int);` 也行，但带上名字更好读。

调用函数时，实参的值被复制一份给形参。函数里改形参，外面的变量纹丝不动。

```c
#include <stdio.h>

void try_change(int x) {
    x = 100;
    printf("函数里 x = %d\n", x);
}

int main(void) {
    int a = 5;
    try_change(a);
    printf("函数外 a = %d\n", a);
    return 0;
}
```

输出是：

```
函数里 x = 100
函数外 a = 5
```

`a` 还是 5。因为传进去的是 `a` 的一份复制品，函数改的是复制品。这套规则叫值传递，C 的普通参数一律如此。

这带来一个限制：**光靠参数没法把结果带回来**。想让函数改动调用方的变量，得把变量的地址传进去，这是第 5 章指针要解决的问题。在那之前，函数结果都靠返回值带出来。

值传递也有好处。函数拿到的是自己的副本，随便改都不会影响外面，写起来不用担心副作用。

`return` 把结果送回调用处，同时立刻结束这个函数。

```c
int max_of(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}
```

第一个 `return` 执行了，后面的语句就不会跑，所以这里不需要 `else`。用这个特点可以提前退出，让代码扁平：

```c
int safe_div(int a, int b) {
    if (b == 0) {
        return 0;      /* 除数为零，直接返回 */
    }
    return a / b;
}
```

**返回类型和 `return` 后面的值必须对得上**。声明成 `int` 却返回 `double`，小数部分会被砍掉。声明成 `int` 却有一条路径没写 `return`，gcc 会警告 `control reaches end of non-void function`，这种函数返回的是垃圾值。

不需要返回任何东西的函数，返回类型写 `void`：

```c
void print_line(void) {
    printf("--------------------\n");
}
```

`void` 函数里可以写一个光秃秃的 `return;` 提前结束，但不能 `return` 一个值。

一个函数只能返回一个值。想同时带回最大值和最小值，要么调用两次，要么用第 5 章的指针参数。

函数里声明的变量只在这个函数里存在，出了大括号就没了。这叫局部变量。

```c
void f(void) {
    int n = 10;
}

void g(void) {
    printf("%d\n", n);    /* 错，g 看不见 f 里的 n */
}
```

不同函数里可以有同名变量，它们互不相干：

```c
#include <stdio.h>

void f(void) {
    int n = 1;
    printf("f 里 n = %d\n", n);
}

int main(void) {
    int n = 99;
    f();
    printf("main 里 n = %d\n", n);   /* 还是 99 */
    return 0;
}
```

作用域甚至细到大括号这一层。下面的 `t` 出了 `if` 就不存在：

```c
if (a > b) {
    int t = a;
    a = b;
    b = t;
}
printf("%d\n", t);    /* 错，t 已经不在了 */
```

写在所有函数外面的变量叫全局变量，所有函数都能读写它。全局变量能用，但**尽量不用**，因为任何一个函数都可能悄悄改掉它，出了问题很难查是谁改的。需要共享数据时，优先用参数传进去、用返回值带出来。

前面处理的都是几个孤零零的变量。一个班有几十个学生，总不能声明几十个变量。这一章用数组把它们装在一起。

```c
#include <stdio.h>

int main(void) {
    int score[8] = {88, 95, 79, 62, 100, 45, 73, 86};
    int n = 8;

    int sum = 0;
    int max = score[0];
    int min = score[0];
    int pass = 0;

    for (int i = 0; i < n; i++) {
        sum += score[i];
        if (score[i] > max) {
            max = score[i];
        }
        if (score[i] < min) {
            min = score[i];
        }
        if (score[i] >= 60) {
            pass++;
        }
    }

    printf("人数 %d\n", n);
    printf("平均 %.1f\n", (double)sum / n);
    printf("最高 %d，最低 %d\n", max, min);
    printf("及格 %d 人，及格率 %.1f%%\n", pass, 100.0 * pass / n);
    return 0;
}
```

运行结果：

```
人数 8
平均 78.5
最高 100，最低 45
及格 7 人，及格率 87.5%
```

一次循环把总分、最高、最低、及格人数全算出来了。要注意最高最低的初值取的是第一个元素，不是 0，否则全是负数的数据会算错。下面把数组讲清楚。

遍历用 `for`，下标从 0 走到长度减 1。

```c
int score[5] = {88, 95, 79, 62, 100};
for (int i = 0; i < 5; i++) {
    printf("第 %d 个是 %d\n", i + 1, score[i]);
}
```

条件写 `i < 5` 而不是 `i <= 5`。写成小于等于就会访问 `score[5]`，那个格子不属于这个数组。

在数组声明所在的函数里，可以用一个技巧算出元素个数：

```c
int score[8] = {88, 95, 79, 62, 100, 45, 73, 86};
int n = sizeof(score) / sizeof(score[0]);   /* n 是 8 */
```

`sizeof` 给出占用的字节数。整个数组的字节数除以单个元素的字节数就是元素个数。

**这个技巧只在数组声明的那个函数里有效**。把数组传给函数以后，函数拿到的只是一个地址，`sizeof` 算出来是地址的大小而不是整个数组的大小。所以 C 的规矩是：**传数组给函数时，必须把长度作为另一个参数一起传**。

```c
double average(int a[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }
    return (double)sum / n;
}
```

调用时写数组名就行，不加方括号：

```c
printf("%.1f\n", average(score, 8));
```

C 没有专门的字符串类型，字符串就是一个 `char` 数组，末尾放一个值为 0 的字符表示到此为止。这个结束标记写作 `\0`。

```c
char s[] = "abc";
```

这个数组实际占 4 个格子：`a`、`b`、`c`、`\0`。所以**声明字符数组时要留出结束符的位置**，想存 20 个字符就要写 `char name[21];`。

用 `%s` 打印，`printf` 从头一直打到遇见 `\0`：

```c
char name[20] = "李雷";
printf("你好，%s\n", name);
```

结束符要是被弄丢了，打印就会一路冲出数组边界，打出一堆乱码。下面这种写法就有这个毛病：

```c
char bad[3] = {'a', 'b', 'c'};   /* 没地方放 \0 */
printf("%s\n", bad);             /* 危险 */
```

可以逐个字符地处理字符串，因为它本来就是数组：

```c
#include <stdio.h>

int main(void) {
    char s[] = "hello";
    for (int i = 0; s[i] != '\0'; i++) {
        printf("%c-", s[i]);
    }
    printf("\n");
    return 0;
}
```

循环条件是当前字符不是结束符，这是最常见的遍历字符串的写法。

处理字符串的函数在 `<string.h>` 里，判断字符类别的在 `<ctype.h>` 里。

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char a[40] = "hello";
    char b[] = "world";

    printf("长度 %zu\n", strlen(a));       /* 5，不含结束符 */
    strcat(a, " ");
    strcat(a, b);
    printf("拼接后 %s\n", a);              /* hello world */

    char c[40];
    strcpy(c, a);
    printf("复制得到 %s\n", c);

    printf("比较 %d\n", strcmp("abc", "abd"));   /* 负数，前者小 */
    printf("相等吗 %d\n", strcmp("abc", "abc") == 0);

    printf("h 是字母吗 %d\n", isalpha('h') != 0);
    printf("7 是数字吗 %d\n", isdigit('7') != 0);
    printf("转大写 %c\n", toupper('h'));
    return 0;
}
```

`isalpha` 和 `isdigit` 成立时返回的是某个非 0 的数，不一定是 1，所以上面加了 `!= 0` 把它变成 1 或 0 再打印。写在 `if` 的条件里则不用管，非 0 就是真。

几个要点：

| 函数 | 作用 | 注意 |
|---|---|---|
| `strlen` | 字符串长度 | 不算结束符，返回值用 `%zu` 打印 |
| `strcpy` | 复制字符串 | 目标数组必须够大，否则越界 |
| `strcat` | 把后一个接到前一个末尾 | 同样要保证目标够大 |
| `strcmp` | 比较两个字符串 | 相等返回 0，**不能用 `==` 比较字符串** |

最后一条要特别记住。`a == b` 比的是两个数组的地址，不是内容，永远不会相等。判断内容一样必须写 `strcmp(a, b) == 0`。

`strcpy` 和 `strcat` 都不检查目标数组够不够大，是缓冲区溢出的常见来源。写的时候自己先算一遍长度。

`scanf("%s", ...)` 读字符串有两个毛病：遇到空格就停，而且不限制长度，输入过长会直接冲垮数组。读一行文字用 `fgets`。

```c
#include <stdio.h>
#include <string.h>

int main(void) {
    char line[100];

    printf("请输入一句话：");
    if (fgets(line, sizeof(line), stdin) == NULL) {
        printf("没读到东西\n");
        return 1;
    }

    line[strcspn(line, "\n")] = '\0';   /* 去掉末尾的换行符 */
    printf("你输入了 %zu 个字符：%s\n", strlen(line), line);
    return 0;
}
```

`fgets` 的三个参数是目标数组、最多读多少字节、从哪读。第二个参数直接写 `sizeof(line)`，就永远不会越界。第三个 `stdin` 表示从键盘读。

`fgets` 会把用户按的回车也存进来，所以要手动去掉。`strcspn(line, "\n")` 给出第一个换行符的位置，把那个位置改成结束符就把换行删掉了。

还有一个坑：`scanf` 和 `fgets` 混着用时，`scanf` 会把回车留在缓冲区里，接下来的 `fgets` 会立刻读到一个空行。避免的办法是要么全程用 `fgets`，要么在 `scanf` 之后手动把这一行剩下的字符读干净。

这一章从一个具体问题开始：写一个函数，把调用方的两个变量对调。

先看不用指针的写法，它是错的：

```c
#include <stdio.h>

void swap_wrong(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main(void) {
    int x = 3, y = 8;
    swap_wrong(x, y);
    printf("x=%d y=%d\n", x, y);   /* 还是 x=3 y=8 */
    return 0;
}
```

第 3 章讲过，参数是复制进去的，函数换的是两个副本，外面的 x 和 y 根本没动。

改成传地址就对了：

```c
#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 3, y = 8;
    printf("交换前 x=%d y=%d\n", x, y);
    swap(&x, &y);
    printf("交换后 x=%d y=%d\n", x, y);
    return 0;
}
```

输出是：

```
交换前 x=3 y=8
交换后 x=8 y=3
```

这段代码里有三个新符号：参数类型里的 `int *`、调用时的 `&x`、函数体里的 `*a`。下面逐个讲。

变量存在内存里，内存的每个字节都有编号，这个编号就是地址。`&` 取出一个变量的地址。

```c
#include <stdio.h>

int main(void) {
    int x = 3;
    double d = 1.5;

    printf("x 的值是 %d\n", x);
    printf("x 的地址是 %p\n", (void *)&x);
    printf("d 的地址是 %p\n", (void *)&d);
    printf("x 占 %zu 字节\n", sizeof(x));
    return 0;
}
```

地址打出来是一串十六进制数，每次运行都不一样，这很正常。用 `%p` 打印地址，前面加 `(void *)` 是为了让类型和 `%p` 对上，不加会有警告。

第 1 章说 `scanf` 的变量前面要加 `&`，现在能解释了：`scanf` 要往变量里写数据，光知道变量当前的值没用，得知道它住在哪儿。所以传地址进去。

而 `printf` 只是读取值打出来，所以不用加 `&`。这就是两者写法不同的原因。

回头看开头那个 `swap`。

```c
void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}
```

调用时写 `swap(&x, &y)`，传进去的是 x 和 y 的地址。参数依然是值传递，函数拿到的是地址的副本。但地址的副本和原地址指向的是同一块内存，所以 `*a = *b` 改的就是外面的 x。

一句话概括：**值传递改不了外面的变量，传地址就能改**。

这个模式在 C 里到处都是。凡是函数需要修改调用方的数据，参数就写成指针。`scanf` 是这样，交换是这样，下一节的多返回值也是这样。

有一个细节要注意。函数里千万别写成这样：

```c
void swap_bad(int *a, int *b) {
    int *t = a;
    a = b;
    b = t;         /* 只换了两个指针的副本，外面的变量没动 */
}
```

这段换的是 a 和 b 这两个指针变量本身，而它们是副本。要改的是它们指向的内容，所以必须带星号。

数组和指针的关系很紧：**数组名在大多数场合会自动变成指向首元素的地址**。

```c
#include <stdio.h>

int main(void) {
    int a[5] = {10, 20, 30, 40, 50};
    int *p = a;          /* 不用写 &a[0]，数组名本身就是地址 */

    printf("%d\n", *p);       /* 10，第一个元素 */
    printf("%d\n", *(p + 2)); /* 30，往后数两个 */
    printf("%d\n", p[2]);     /* 30，和上面完全等价 */
    printf("%d\n", a[2]);     /* 30 */

    for (int i = 0; i < 5; i++) {
        printf("%d ", *(a + i));
    }
    printf("\n");
    return 0;
}
```

`p + 1` 不是地址加 1 个字节，而是往后挪一个元素。`int` 占 4 字节，所以 `p + 1` 的地址比 p 大 4。指针类型决定了这一步跨多远，这就是指针要分类型的原因。

由此得到一条等式：**`a[i]` 就是 `*(a + i)` 的另一种写法**，两者完全一样。

反过来，两个指向同一个数组的指针相减，得到的是它们之间隔了几个元素：

```c
int a[5] = {10, 20, 30, 40, 50};
printf("%ld\n", (long)(&a[3] - a));   /* 打出 3 */
```

这也解释了第 4 章的说法：数组传给函数会退化成指针。函数收到的其实是 `int *`，所以 `sizeof` 在函数里算不出数组长度，必须另外传长度。下面这两种写法在函数参数里是一回事：

```c
double average(int a[], int n);
double average(int *a, int n);
```

函数只能 `return` 一个值。想同时带回好几个结果，就把存放结果的变量地址传进去，让函数往里写。

```c
#include <stdio.h>

void min_max(const int *a, int n, int *out_min, int *out_max) {
    int mn = a[0];
    int mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < mn) {
            mn = a[i];
        }
        if (a[i] > mx) {
            mx = a[i];
        }
    }
    *out_min = mn;
    *out_max = mx;
}

int main(void) {
    int a[6] = {17, 4, 92, 38, 55, 71};
    int lo = 0, hi = 0;

    min_max(a, 6, &lo, &hi);
    printf("最小 %d，最大 %d\n", lo, hi);
    return 0;
}
```

输出是 `最小 4，最大 92`。

第一个参数写成 `const int *a`，`const` 表示这个函数只读不写这块数据。加上它有两个好处：读代码的人一眼知道数组不会被改，写错了编译器还会拦住。**只读的指针参数都加 `const`，这是好习惯**。

按惯例，用来输出结果的参数名字带上 `out_` 之类的前缀，调用的人一看就知道哪些参数是往里写的。

指针出错的后果比普通变量严重，因为它直接操作内存。有两种情况要防。

**第一种，指针没初始化就用。**

```c
int *p;        /* p 里是随机地址 */
*p = 10;       /* 往一个不知道哪儿的地方写，程序多半崩掉 */
```

崩掉时的报错是 Segmentation fault，意思是访问了不该访问的内存。声明指针时如果还不知道指向哪，就先赋成 `NULL`：

```c
int *p = NULL;
```

`NULL` 是一个特殊的地址值，表示这个指针目前不指向任何东西。

**第二种，用之前不检查是不是空。**

```c
void print_all(const int *a, int n) {
    if (a == NULL) {
        printf("没有数据\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
}
```

函数收到指针参数，先判一下是不是 `NULL` 再用，能挡掉一大类崩溃。

还有一种情况：指针指向的变量已经消失了，比如函数返回了一个局部变量的地址。

```c
int *bad(void) {
    int x = 10;
    return &x;      /* 错，函数一结束 x 就没了 */
}
```

gcc 会警告 `function returns address of local variable`。要返回数据，要么返回值本身，要么让调用方先准备好空间再把地址传进来。

