#include <stdio.h>

int is_prime(int n);
int gcd(int a, int b);
int sum_digits(int n);

int is_prime(int n) {
    if (n < 2) {
        return 0;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int sum_digits(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int main(void) {
    printf("97 是质数吗 %d\n", is_prime(97));
    printf("84 和 126 的最大公约数 %d\n", gcd(84, 126));
