#include <stdio.h>
#include <string.h>
#include <ctype.h>

int is_palindrome(const char *s);

int is_palindrome(const char *s) {
    int i = 0;
    int j = (int)strlen(s) - 1;
    while (i < j) {
        if (s[i] != s[j]) {
            return 0;
        }
        i++;
        j--;
    }
    return 1;
}

int main(void) {
    char s[] = "Level 2026 up!";

    int alpha = 0, digit = 0, space = 0, other = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        if (isalpha(c)) {
            alpha++;
        } else if (isdigit(c)) {
            digit++;
        } else if (c == ' ') {
            space++;
        } else {
