void stats(const int *a, int n, int *out_max, int *out_min, double *out_avg);

void stats(const int *a, int n, int *out_max, int *out_min, double *out_avg) {
    int mx = a[0];
    int mn = a[0];
    int sum = 0;

    for (int i = 0; i < n; i++) {
        if (a[i] > mx) {
            mx = a[i];
        }
        if (a[i] < mn) {
            mn = a[i];
        }
        sum += a[i];
    }

    *out_max = mx;
    *out_min = mn;
    *out_avg = (double)sum / n;
}

