#include <stdio.h>

int remove_value(int *a, int n, int v);

int remove_value(int *a, int n, int v) {
    int *write = a;
    for (int *read = a; read < a + n; read++) {
        if (*read != v) {
            *write = *read;
            write++;
        }
    }
    return (int)(write - a);
}

int main(void) {
    int a[7] = {3, 7, 3, 1, 9, 3, 5};

    int m = remove_value(a, 7, 3);
    printf("删除后长度 %d\n", m);

    printf("剩下");
    for (int i = 0; i < m; i++) {
        printf(" %d", *(a + i));
    }
    printf("\n");

    int m2 = remove_value(a, m, 8);
    printf("删除不存在的 8 后长度 %d\n", m2);

    printf("下标 2 距首元素 %ld 个元素\n", (long)(&a[2] - a));
